let platforms=[],pickups=[],crates=[],hazards=[],enemies=[],checkpointObjs=[],boss=null,gate=null,decor=[],gameMode='menu',toastTime=0,clock=0,fruitCount=0,lives=3,checkpoint={x:0,y:0,z:4},invuln=0,levelWon=false;
