const keys={left:false,right:false,forward:false,back:false,jump:false,spin:false,slide:false};let jumpQueued=false,spinQueued=false;
function clearGroup(g){while(g.children.length){const o=g.children.pop();if(o.geometry)o.geometry.dispose();g.remove(o);}}
function platform(x,y,z,w,d,theme=worlds[worldIndex]){const m=mat(theme.side);const p=box(x,y-.42,z,w,.84,d,m,groups.level);p.userData={x,y,z,w,d,top:theme.top};const cap=box(x,y+.025,z,w,.12,d,mat(theme.top),groups.level);platforms.push(p);return p;}
function fruit(x,y,z,secret=false){const g=new THREE.Group();g.position.set(x,y,z);groups.level.add(g);ball(0,0,0,.2,.24,.2,shared.fruit,g);ball(-.07,.23,0,.055,.11,.04,shared.leaf,g);ball(-.075,.02,.17,.025,.025,.02,shared.white,g);g.userData={base:y,phase:Math.random()*6,secret};pickups.push(g);return g;}
function crate(x,y,z,type='fruit'){const g=new THREE.Group();g.position.set(x,y,z);groups.level.add(g);const cm=mat(type==='nitro'?0x71d64e:type==='tnt'?0xdf5144:0xb97844);box(0,.45,0,.86,.86,.86,cm,g);for(const q of [-1,1]){box(q*.28,.45,.445,.075,.78,.04,shared.woodL,g);box(0,.45+q*.28,.45,.78,.075,.04,shared.woodL,g);}const label=type==='fruit'?'✦':type==='tnt'?'TNT':'N';// billboard-like bright face marker
const sign=box(0,.47,.49,.3,.28,.05,type==='fruit'?shared.gold:type==='tnt'?shared.white:mat(0x263c51),g);g.userData={type,alive:true,timer:0,sign};crates.push(g);if(type==='fruit')for(let i=0;i<3;i++)fruit(x+(i-1)*.34,y+1.25,z);return g;}
function enemy(x,y,z){const g=new THREE.Group();g.position.set(x,y,z);groups.level.add(g);ball(0,.32,0,.38,.35,.36,shared.blue,g);ball(0,.58,.05,.28,.24,.27,mat(worldIndex===2?0xa9d9e8:0x42c8d0),g);for(const q of [-1,1]){ball(q*.11,.62,.29,.075,.1,.05,shared.white,g);ball(q*.12,.62,.335,.027,.05,.02,shared.dark,g);const h=mesh(new THREE.ConeGeometry(.1,.26,6),shared.gold,q*.23,.84,-.04,g);h.rotation.z=q*.35;}g.userData={baseX:x,phase:Math.random()*5,alive:true,y};enemies.push(g);}
function spike(x,y,z){const g=new THREE.Group();g.position.set(x,y,z);groups.level.add(g);box(0,.09,0,1.35,.18,.85,shared.red,g);for(let i=-1;i<=1;i++){const c=mesh(new THREE.ConeGeometry(.25,.55,5),shared.dark,i*.4,.42,0,g);c.rotation.z=Math.PI;}hazards.push({x,y,z,type:'spike',group:g});}
function tree(x,z,theme=worlds[worldIndex],scale=1){const g=new THREE.Group();g.position.set(x,0,z);groups.world.add(g);if(worldIndex===0){const t=mesh(new THREE.CylinderGeometry(.13*scale,.24*scale,2*scale,7),shared.wood,0,scale,0,g);t.rotation.z=.1;for(let i=0;i<5;i++){const a=i*Math.PI*2/5;const l=mesh(new THREE.ConeGeometry(.36*scale,1.7*scale,5),mat(i%2?theme.accent:0x45c876),Math.cos(a)*.62*scale,1.75*scale,Math.sin(a)*.62*scale,g);l.rotation.z=Math.cos(a)*.85;l.rotation.x=Math.sin(a)*.85;}}else if(worldIndex===1){box(0,.9*scale,0,.8*scale,1.8*scale,.75*scale,mat(theme.side),g);ball(0,2*scale,0,.9*scale,.5*scale,.9*scale,mat(theme.accent),g);}else{const r=mesh(new THREE.ConeGeometry(.9*scale,2.4*scale,7),mat(theme.accent),0,1.2*scale,0,g);if(worldIndex===2)r.material=mat(0xe9f9ff);if(worldIndex===3)r.material=mat(0x633f48);if(worldIndex===4){box(0,.8*scale,0,1.4*scale,1.6*scale,.7*scale,mat(0x617c83),g);box(0,1.9*scale,0,.35*scale,.25*scale,.35*scale,shared.gold,g);}if(worldIndex===5){box(0,.85*scale,0,.9*scale,1.7*scale,.8*scale,mat(theme.side),g);const roof=mesh(new THREE.ConeGeometry(.8*scale,.8*scale,4),mat(theme.accent),0,2*scale,0,g);roof.rotation.y=Math.PI/4;}}return g;}
function addBoss(){const g=new THREE.Group();g.position.set(0,0,-94);groups.level.add(g);ball(0,1.1,0,1.05,1.1,.85,mat(worlds[worldIndex].accent),g);ball(0,2,0,.73,.75,.68,mat(worlds[worldIndex].top),g);for(const q of [-1,1]){ball(q*.27,2.05,.58,.14,.18,.09,shared.white,g);ball(q*.28,2.05,.66,.05,.09,.04,shared.dark,g);const horn=mesh(new THREE.ConeGeometry(.2,.6,6),shared.gold,q*.52,2.62,-.08,g);horn.rotation.z=-q*.35;}ball(0,1.74,.65,.25,.07,.07,shared.dark,g);const ring=mesh(new THREE.TorusGeometry(1.3,.09,8,24),shared.gold,0,.13,0,g);ring.rotation.x=Math.PI/2;boss={group:g,hp:3,max:3,phase:0,open:0,stun:0};}
function buildLevel(w,l){worldIndex=w;levelIndex=l;const theme=worlds[w];scene.background=new THREE.Color(theme.sky);scene.fog=new THREE.Fog(theme.sky,30,112);while(groups.level.children.length){const o=groups.level.children[0];groups.level.remove(o);}while(groups.world.children.length){const o=groups.world.children[0];groups.world.remove(o);}platforms=[];pickups=[];crates=[];hazards=[];enemies=[];checkpointObjs=[];boss=null;gate=null;
// Endless-looking themed scenery, with a clear playable floating trail.
const water=mesh(new THREE.PlaneGeometry(240,240),mat(theme.ground,.5),0,-3,-48,groups.world);water.rotation.x=-Math.PI/2;
for(let i=0;i<32;i++){const z=6-i*4;const gap=(l===0?[-38,-70]:[-30,-58,-82]).some(g=>Math.abs(z-g)<3.1);if(gap)continue;const step=Math.floor(i/4)%4===2?0.35:0;const side=Math.sin(i*.72)*.75;const width=(i%7===4?5.7:7);platform(side,step,z,width,4.2,theme);if(i%3===0){tree(-7-(i%4)*.35,z-1,theme,.7+(i%3)*.1);tree(7+(i%5)*.25,z-2,theme,.75);}if(i%6===1){const rock=mesh(new THREE.DodecahedronGeometry(.8,0),mat(theme.accent),side+(i%2?4:-4),.15,z,groups.world);rock.scale.set(1.3,.9,1.1);}}
// Launch deck and stepping stones across the signature gaps.
platform(0,0,5,8,8,theme);const gaps=l===0?[-38,-70]:[-30,-58,-82];for(const gz of gaps){platform(gz===-58?1.8:-1.7,.35,gz,2.4,2.1,theme);fruit(gz===-58?1.8:-1.7,1.55,gz);}
// Fruit trails, smashable boxes, hazards, and roaming goofballs.
for(let i=0;i<20;i++){const z=-5-i*4.2,x=Math.sin(i*1.27)*2.1;const y=(Math.floor(i/4)%4===2?.35:0)+1.2;if(i%5===1)crate(x,y-.75,z,i%10===1?'tnt':'fruit');else if(i%5===3){spike(x,y-.95,z);fruit(x+(x>0?-2.2:2.2),y+.15,z-.5);}else if(i%5===4){enemy(x,y-.9,z);fruit(x+(x>0?-2.1:2.1),y+.45,z-.4);}else{fruit(x,y,z);if(i%4===0){fruit(x+.65,y+.65,z-1);fruit(x+1.2,y+.85,z-2);}}}
// Nitro is a proximity trap; a tucked-away side path rewards curious explorers.
crate(-1.9,.35,-52,'nitro');for(let i=0;i<4;i++){platform(5.2,.25,-47-i*3,2.5,3.2,theme);fruit(5.2,1.55,-47-i*3,true);}crate(0,.35,-64,'tnt');
// Checkpoint totems, finish gate, and a dramatic boss arena on the second level of each world.
for(const z of [-48,-78]){const cp=new THREE.Group();cp.position.set(-2.8,.1,z);groups.level.add(cp);box(0,.6,0,.32,1.2,.32,shared.white,cp);ball(0,1.35,0,.28,.28,.28,shared.gold,cp);cp.userData={active:false,z};checkpointObjs.push(cp);}
const endZ=-101;platform(0,0,endZ,12,12,theme);const gateGroup=new THREE.Group();gateGroup.position.set(0,0,-98);groups.level.add(gateGroup);for(const x of [-2.4,2.4]){box(x,1.5,0,.35,3,.4,mat(theme.accent),gateGroup);ball(x,3.1,0,.38,.38,.38,shared.gold,gateGroup);}box(0,2.9,0,5.1,.38,.45,mat(theme.accent),gateGroup);const ring=mesh(new THREE.TorusGeometry(1.35,.16,10,26),shared.gold,0,1.55,.02,gateGroup);gate={z:-98,group:gateGroup};
if(l===1){addBoss();uiObjective('Defeat the guardian, then reach the gateway!');}else uiObjective('Find the trail, gather glowfruits and reach the gate!');
// World landmarks beyond the route add depth and a strong theme silhouette.
for(let i=0;i<11;i++){const z=-8-i*9;tree(i%2?10:-10,z,theme,1.4+(i%3)*.18);}player.x=0;player.y=0;player.z=4;player.vx=0;player.vy=0;player.grounded=true;player.spin=0;player.slide=0;player.stun=0;checkpoint={x:0,y:0,z:4};fruitCount=0;lives=3;invuln=0;levelWon=false;refreshHud();$('#worldLabel').textContent=theme.name.toUpperCase();$('#progressFill').style.width='0%';groups.hero.visible=true;makeHero();}
function uiObjective(text){$('#objective').textContent=text;}function refreshHud(){$('#fruitCount').textContent=String(fruitCount).padStart(2,'0');$('#lifeCount').textContent=String(lives);}function toast(text){const t=$('#toast');t.textContent=text;t.classList.add('show');toastTime=1.5;}

