function uiObjective(text){$('#objective').textContent=text;}function refreshHud(){$('#fruitCount').textContent=String(fruitCount).padStart(2,'0');$('#lifeCount').textContent=String(lives);}function toast(text){const t=$('#toast');t.textContent=text;t.classList.add('show');toastTime=1.5;}
function makeHero(){while(groups.hero.children.length)groups.hero.remove(groups.hero.children[0]);const tint=mat(characters[charIndex].color);const body=new THREE.Group();groups.hero.add(body);ball(0,.82,0,.4,.52,.32,tint,body);ball(0,1.42,0,.48,.48,.4,tint,body);ball(0,1.15,.22,.35,.24,.25,mat(0xffdfbd),body);ball(0,1.36,.42,.29,.17,.14,mat(0xffdfbd),body);ball(0,1.4,.54,.08,.06,.05,shared.dark,body);for(const x of [-.19,.19]){ball(x,1.59,.34,.12,.16,.09,shared.white,body);ball(x+.02,1.58,.42,.05,.08,.035,shared.dark,body);const ear=ball(x*1.6,1.83,-.02,.16,.25,.12,tint,body);ear.rotation.z=-x;}const tail=ball(0,.53,-.42,.12,.16,.4,characters[charIndex].name==='Zuzu'?mat(0x55c77f):tint,body);tail.rotation.x=-.5;const arms=[],legs=[];for(const x of [-1,1]){const a=new THREE.Group();a.position.set(x*.37,1.05,0);body.add(a);ball(0,-.22,0,.13,.31,.13,tint,a);ball(0,-.45,.04,.18,.14,.16,shared.white,a);arms.push(a);const leg=new THREE.Group();leg.position.set(x*.2,.45,0);body.add(leg);ball(0,-.16,0,.13,.27,.13,tint,leg);ball(0,-.37,.13,.23,.12,.31,shared.red,leg);legs.push(leg);}groups.hero.userData={body,arms,legs};}
function renderCharacterChoices(){const grid=$('#characterGrid');grid.innerHTML='';characters.forEach((c,i)=>{const b=document.createElement('button');b.className='choice'+(charIndex===i?' selected':'');b.innerHTML=`<span class="emoji">${c.emoji}</span>${c.name}<small>${['Quick feet','Steady hops','Big spin'][i]}</small>`;b.onclick=()=>{charIndex=i;renderCharacterChoices();};grid.append(b);});}
function renderWorlds(){const grid=$('#worldGrid');grid.innerHTML='';$('#unlockText').textContent=`${Math.min(furthest,12)} / 12 levels discovered · Choose any unlocked level`;worlds.forEach((w,wi)=>{const card=document.createElement('div');card.className='choice world'+(wi*2>furthest?' locked':'');card.innerHTML=`<span class="emoji">${w.icon}</span>${w.name}<small>Two curious levels</small>`;const a=document.createElement('button');a.className='back';a.textContent='1 · Trail';a.disabled=wi*2>furthest;a.onclick=()=>startLevel(wi,0);const b=document.createElement('button');b.className='back';b.textContent='2 · Guardian';b.disabled=wi*2+1>furthest;b.onclick=()=>startLevel(wi,1);card.append(document.createElement('br'),a,b);grid.append(card);});}
function showPanel(id){for(const e of document.querySelectorAll('.overlay'))e.classList.add('hidden');if(id)$('#'+id).classList.remove('hidden');}
function startLevel(w,l){buildLevel(w,l);gameMode='play';showPanel(null);toast(`${worlds[w].name} · ${l===0?'The Winding Trail':'Guardian Grounds'}`);}
function completeLevel(){if(levelWon)return;levelWon=true;gameMode='result';const stage=worldIndex*2+levelIndex;furthest=Math.max(furthest,stage+1);localStorage.setItem('cloudstepSave',JSON.stringify({furthest}));$('#resultEyebrow').textContent=levelIndex===1?'GUARDIAN DEFEATED!':'LEVEL CLEAR!';$('#resultTitle').innerHTML=levelIndex===1?'ISLAND SAVED!<span>THE GATEWAY OPENS</span>':'HURRAY!<span>GATEWAY FOUND</span>';$('#resultText').textContent=`${characters[charIndex].name} found ${fruitCount} glowfruit${fruitCount===1?'':'s'} and earned ${lives} heart${lives===1?'':'s'}.`;$('#resultBtn').textContent=stage<11?'NEXT ADVENTURE ➜':'PLAY AGAIN ➜';renderWorlds();showPanel('result');}
function damage(reason){if(invuln>0||gameMode!=='play')return;lives--;invuln=1.5;player.stun=.38;player.vy=4;player.grounded=false;toast(reason);refreshHud();if(lives<=0){setTimeout(()=>{if(gameMode==='play')showResult(false);},380);}else{player.x=checkpoint.x;player.y=checkpoint.y;player.z=checkpoint.z;player.vy=0;}}
function showResult(won){gameMode='result';$('#resultEyebrow').textContent=won?'LEVEL CLEAR!':'OUT OF LIVES!';$('#resultTitle').innerHTML=won?'HURRAY!<span>GATEWAY FOUND</span>':'OH, BISCUITS!<span>LET’S TRY AGAIN</span>';$('#resultText').textContent=won?`You found ${fruitCount} glowfruit!`:'The isles are still waiting for you. Take another run!';$('#resultBtn').textContent=won?'NEXT ADVENTURE ➜':'RETRY LEVEL ↻';$('#resultBtn').onclick=()=>won?advanceLevel():startLevel(worldIndex,levelIndex);showPanel('result');}
