function keyChange(k,v){if(k==='jump'&&v&&!keys.jump)jumpQueued=true;if(k==='spin'&&v&&!keys.spin)spinQueued=true;if(k in keys)keys[k]=v;}
addEventListener('keydown',e=>{const k=e.key.toLowerCase();if([' ','arrowleft','arrowright','arrowup','arrowdown'].includes(k))e.preventDefault();if(k==='escape'){if(gameMode==='play'){gameMode='pause';showPanel('worlds');renderWorlds();toast('Paused · select a level or resume from the menu');}return;}if(k==='a'||k==='arrowleft')keyChange('left',true);if(k==='d'||k==='arrowright')keyChange('right',true);if(k==='w'||k==='arrowup')keyChange('forward',true);if(k==='s'||k==='arrowdown')keyChange('back',true);if(k===' ')keyChange('jump',true);if(k==='j'||k==='k')keyChange('spin',true);if(k==='shift')keyChange('slide',true);});
addEventListener('keyup',e=>{const k=e.key.toLowerCase();if(k==='a'||k==='arrowleft')keyChange('left',false);if(k==='d'||k==='arrowright')keyChange('right',false);if(k==='w'||k==='arrowup')keyChange('forward',false);if(k==='s'||k==='arrowdown')keyChange('back',false);if(k===' ')keyChange('jump',false);if(k==='j'||k==='k')keyChange('spin',false);if(k==='shift')keyChange('slide',false);});
for(const btn of document.querySelectorAll('.touch')){const name=btn.dataset.key;const on=e=>{e.preventDefault();btn.setPointerCapture?.(e.pointerId);keyChange(name,true);};const off=e=>{e.preventDefault();keyChange(name,false);};btn.addEventListener('pointerdown',on);btn.addEventListener('pointerup',off);btn.addEventListener('pointercancel',off);btn.addEventListener('lostpointercapture',off);}

