function floorAt(x,z){let y=null;for(const p of platforms){const d=p.userData;if(Math.abs(x-d.x)<=d.w/2-.05&&Math.abs(z-d.z)<=d.d/2){if(y===null||d.y>y)y=d.y;}}return y===null?null:y;}
function burstAt(x,z){for(const p of pickups){if(p.visible&&Math.abs(p.position.x-x)<2.1&&Math.abs(p.position.z-z)<2.1)p.visible=false;}for(const c of crates){if(c.userData.alive&&Math.abs(c.position.x-x)<2.2&&Math.abs(c.position.z-z)<2.2){c.userData.alive=false;c.visible=false;}}for(const e of enemies){if(e.userData.alive&&Math.abs(e.position.x-x)<2.4&&Math.abs(e.position.z-z)<2.4){e.userData.alive=false;e.visible=false;}}}
